"use client";

import * as React from "react";
import styles from "../styles/icon-button.module.css";

type IconName = "bell" | "heart" | "settings" | "share" | "plus" | "trash" | "search";

export interface IconButtonProps {
  /** Accessible name, also shown as the hover/focus label */
  label?: string;
  /** Built-in inline SVG icon */
  icon?: IconName;
  /** Custom icon; overrides `icon` */
  children?: React.ReactNode;
  /** Visual style */
  variant?: "solid" | "soft" | "outline" | "ghost";
  /** Corner shape */
  shape?: "round" | "square";
  /** Size preset */
  size?: "sm" | "md" | "lg";
  /** Show the floating label on hover and keyboard focus */
  showLabel?: boolean;
  /** Side the floating label appears on */
  labelSide?: "top" | "bottom";
  /** Play a ripple from the press point */
  ripple?: boolean;
  /** Brand color for solid/soft variants and the ripple */
  accentColor?: string;
  /** Disable the button */
  disabled?: boolean;
  /** Click handler */
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const PATHS: Record<IconName, string> = {
  bell: "M6 8a6 6 0 1 1 12 0c0 7 3 9 3 9H3s3-2 3-9M10.3 21a1.94 1.94 0 0 0 3.4 0",
  heart: "M19 14c1.5-1.5 3-3.2 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.8 0-3 .5-4.5 2-1.5-1.5-2.7-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4 3 5.5l7 7z",
  settings: "M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z",
  share: "M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM8.6 13.5l6.8 4M15.4 6.5l-6.8 4",
  plus: "M12 5v14M5 12h14",
  trash: "M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6M10 11v6M14 11v6",
  search: "M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16zM21 21l-4.3-4.3",
};

interface Ripple {
  id: number;
  x: number;
  y: number;
  r: number;
}

export function IconButton({
  label = "Notifications",
  icon = "bell",
  children,
  variant = "soft",
  shape = "round",
  size = "md",
  showLabel = true,
  labelSide = "top",
  ripple = true,
  accentColor = "#6366f1",
  disabled = false,
  onClick,
  className = "",
  style,
}: IconButtonProps) {
  const [ripples, setRipples] = React.useState<Ripple[]>([]);
  const nextId = React.useRef(0);

  const onPointerDown = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (!ripple || disabled) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const r = Math.hypot(Math.max(x, rect.width - x), Math.max(y, rect.height - y));
    const id = nextId.current++;
    setRipples((list) => [...list.slice(-3), { id, x, y, r }]);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
    if (!ripple || disabled || e.repeat || (e.key !== "Enter" && e.key !== " ")) return;
    const { width, height } = e.currentTarget.getBoundingClientRect();
    const id = nextId.current++;
    setRipples((list) => [...list.slice(-3), { id, x: width / 2, y: height / 2, r: Math.hypot(width, height) / 2 }]);
  };

  const cls = [styles.root, styles[variant], styles[shape], styles[size]].filter(Boolean).join(" ");

  return (
    <span
      className={`${styles.wrap} ${className}`.trim()}
      data-side={labelSide}
      style={{ "--mf-ib-accent": accentColor, ...style } as React.CSSProperties}
    >
      <button
        type="button"
        aria-label={label}
        disabled={disabled}
        onPointerDown={onPointerDown}
        onKeyDown={onKeyDown}
        onClick={onClick}
        className={cls}
      >
        <span className={styles.ripples} aria-hidden="true">
          {ripples.map((rp) => (
            <span
              key={rp.id}
              className={styles.ripple}
              style={{ left: rp.x - rp.r, top: rp.y - rp.r, width: rp.r * 2, height: rp.r * 2 }}
              onAnimationEnd={() => setRipples((list) => list.filter((it) => it.id !== rp.id))}
            />
          ))}
        </span>
        <span className={styles.icon} aria-hidden="true">
          {children ?? (
            <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d={PATHS[icon] ?? PATHS.bell} />
            </svg>
          )}
        </span>
      </button>
      {showLabel && label ? (
        <span className={styles.tip} aria-hidden="true">
          {label}
        </span>
      ) : null}
    </span>
  );
}

.wrap {
  position: relative;
  display: inline-flex;
  color: var(--mf-fg, #f4f4f6);
}

.root {
  --mf-ib-size: 2.5rem;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--mf-ib-size);
  height: var(--mf-ib-size);
  padding: 0;
  border: 1px solid transparent;
  overflow: hidden;
  font: inherit;
  cursor: pointer;
  isolation: isolate;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, box-shadow 160ms ease,
    transform 200ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.root:active:not(:disabled) {
  transform: scale(0.92);
  transition-duration: 160ms, 160ms, 160ms, 160ms, 80ms;
}

.root:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.root:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sm {
  --mf-ib-size: 2rem;
}

.md {
  --mf-ib-size: 2.5rem;
}

.lg {
  --mf-ib-size: 3rem;
}

.round {
  border-radius: 999px;
}

.square {
  border-radius: 0.625rem;
}

.icon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  width: 45%;
  height: 45%;
  transition: transform 220ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.root:hover:not(:disabled) .icon {
  transform: scale(1.08) rotate(-6deg);
}

.solid {
  background-color: var(--mf-ib-accent, #6366f1);
  color: #ffffff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.solid:hover:not(:disabled) {
  box-shadow: 0 6px 18px -6px color-mix(in srgb, var(--mf-ib-accent, #6366f1) 70%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.soft {
  background-color: color-mix(in srgb, var(--mf-ib-accent, #6366f1) 16%, transparent);
  color: var(--mf-ib-accent, #6366f1);
}

.soft:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--mf-ib-accent, #6366f1) 24%, transparent);
}

.outline {
  background-color: var(--mf-surface, #141419);
  border-color: var(--mf-border, #2e2e38);
  color: var(--mf-fg, #f4f4f6);
}

.outline:hover:not(:disabled) {
  background-color: var(--mf-surface-raised, #1b1b22);
  border-color: var(--mf-border-strong, #52525b);
}

.ghost {
  background-color: transparent;
  color: var(--mf-muted, #a1a1aa);
}

.ghost:hover:not(:disabled) {
  background-color: var(--mf-surface-raised, #1b1b22);
  color: var(--mf-fg, #f4f4f6);
}

.ripples {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.ripple {
  position: absolute;
  border-radius: 999px;
  background-color: currentColor;
  opacity: 0.28;
  transform: scale(0);
  animation: mf-ib-ripple 520ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.solid .ripple {
  background-color: #ffffff;
}

@keyframes mf-ib-ripple {
  to {
    transform: scale(1);
    opacity: 0;
  }
}

.tip {
  position: absolute;
  left: 50%;
  z-index: 10;
  padding: 0.3125rem 0.5rem;
  border-radius: 0.375rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface-raised, #1b1b22);
  color: var(--mf-fg, #f4f4f6);
  font-size: 0.75rem;
  font-weight: 500;
  line-height: 1.2;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 8px 24px -8px rgba(0, 0, 0, 0.45);
  opacity: 0;
  transition: opacity 150ms ease, transform 200ms cubic-bezier(0.16, 1, 0.3, 1);
}

.wrap[data-side="top"] .tip {
  bottom: calc(100% + 0.5rem);
  transform: translate(-50%, 4px) scale(0.96);
}

.wrap[data-side="bottom"] .tip {
  top: calc(100% + 0.5rem);
  transform: translate(-50%, -4px) scale(0.96);
}

.wrap:hover .root:not(:disabled) + .tip,
.root:focus-visible + .tip {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
  transition-delay: 120ms;
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .icon,
  .tip {
    transition: none;
  }

  .root:active:not(:disabled),
  .root:hover:not(:disabled) .icon {
    transform: none;
  }

  .ripple {
    display: none;
  }

  .wrap[data-side] .tip {
    transform: translate(-50%, 0);
  }
}

