"use client";

import { useState } from "react";

export function IconButtonTailwind({ label = "Notifications" }) {
  const [ripples, setRipples] = useState<{ id: number; x: number; y: number }[]>([]);
  return (
    <span className="group relative inline-flex">
      <button
        type="button"
        aria-label={label}
        onPointerDown={(e) => {
          const r = e.currentTarget.getBoundingClientRect();
          setRipples((l) => [...l, { id: e.timeStamp, x: e.clientX - r.left, y: e.clientY - r.top }]);
        }}
        className="relative grid size-10 place-items-center overflow-hidden rounded-full bg-indigo-500/15 text-indigo-400 transition active:scale-90 hover:bg-indigo-500/25 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2"
      >
        {ripples.map((r) => (
          <span key={r.id} onAnimationEnd={() => setRipples((l) => l.filter((x) => x.id !== r.id))} style={{ left: r.x - 40, top: r.y - 40 }} className="absolute size-20 animate-ping rounded-full bg-current opacity-30 [animation-iteration-count:1]" />
        ))}
        <svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M6 8a6 6 0 1 1 12 0c0 7 3 9 3 9H3s3-2 3-9M10.3 21a1.94 1.94 0 0 0 3.4 0" /></svg>
      </button>
      <span aria-hidden="true" className="pointer-events-none absolute bottom-full left-1/2 mb-2 -translate-x-1/2 translate-y-1 whitespace-nowrap rounded-md border border-zinc-800 bg-zinc-900 px-2 py-1 text-xs text-zinc-100 opacity-0 transition group-hover:translate-y-0 group-hover:opacity-100">{label}</span>
    </span>
  );
}
